import sys

def countStrings(S):
    n = len(S)
    if n == 2:
        return 1

    freq = {}
    for c in S:
        freq[c] = freq.get(c, 0) + 1

    has_duplicate = any(count > 1 for count in freq.values())

    total_swaps = n * (n - 1) // 2

    if has_duplicate:
        duplicate_pairs = 0
        for count in freq.values():
            if count > 1:
                duplicate_pairs += count * (count - 1) // 2

        return total_swaps - duplicate_pairs + 1
    else:
        return total_swaps

def main():
    S = sys.stdin.read().strip()
    result = countStrings(S)
    print(result)

if __name__ == "__main__":
    main()
